cel</button><button class="btn btn-primary">Save plan</button></div></form></div></div>

<script>
window.addEventListener('DOMContentLoaded',function(){function fill(form,data){Object.keys(data||{}).forEach(function(key){var field=form.elements[key];if(!field)return;if(field.type==='checkbox')field.checked=Number(data[key])===1;else field.value=data[key]==null?'':data[key];});}
$('#quote-service-modal').on('show.bs.modal',function(e){var form=this.querySelector('form'),raw=e.relatedTarget.getAttribute('data-service'),data=raw?JSON.parse(raw):{};form.reset();fill(form,data);form.querySelector('.modal-title').textContent=data.id?'Edit service':'Add service';if(!data.id){form.elements.active.checked=true;form.elements.taxable.checked=true;form.elements.quote_enabled.checked=true;}});
$('#quote-package-modal').on('show.bs.modal',function(e){fill(this.querySelector('form'),JSON.parse(e.relatedTarget.getAttribute('data-package')));});
$('#quote-package-item-modal').on('show.bs.modal',function(e){var data=JSON.parse(e.relatedTarget.getAttribute('data-item'));data.package_item_id=data.id;fill(this.querySelector('form'),data);});
$('#quote-plan-modal').on('show.bs.modal',function(e){var form=this.querySelector('form'),type=e.relatedTarget.getAttribute('data-type'),data=JSON.parse(e.relatedTarget.getAttribute('data-plan'));data.plan_id=data.id;data.plan_type=type;form.reset();fill(form,data);form.querySelector('.support-plan-fields').style.display=type==='support'?'contents':'none';form.querySelector('.membership-plan-fields').style.display=type==='membership'?'contents':'none';});});
</script>
